package events

import (
	"crypto/rand"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/oklog/ulid/v2"
)

// IDGen produces monotonic ULIDs for Event.ID and batch_id. IDs generated by
// the same IDGen sort strictly increasing even within one millisecond or when
// the wall clock steps backwards. It is safe for concurrent use.
type IDGen struct {
	mu      sync.Mutex
	entropy *ulid.MonotonicEntropy
	lastMs  uint64
}

// NewIDGen returns a generator reading randomness from entropy; nil means crypto/rand.
func NewIDGen(entropy io.Reader) *IDGen {
	if entropy == nil {
		entropy = rand.Reader
	}
	return &IDGen{entropy: ulid.Monotonic(entropy, 0)}
}

// New returns the next ULID for time t as a 26-character string.
func (g *IDGen) New(t time.Time) (string, error) {
	g.mu.Lock()
	defer g.mu.Unlock()
	ms := ulid.Timestamp(t)
	if ms < g.lastMs {
		ms = g.lastMs // clock went backwards: stay in the last millisecond to keep order
	}
	id, err := ulid.New(ms, g.entropy)
	if err != nil {
		return "", fmt.Errorf("events: new ulid: %w", err)
	}
	g.lastMs = ms
	return id.String(), nil
}
